package com.patrick.fintech.loan_backend.service;
import com.patrick.fintech.loan_backend.model.*; import com.patrick.fintech.loan_backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class PaymentSettlementService{
 private final PaymentSettlementRepository repo; private final PaymentRepository paymentRepo; private final BankStatementLineRepository statementRepo;
 @Transactional public PaymentSettlement record(Organization org,String provider,String providerReference,String internalRef,BigDecimal amount,String currency,LocalDate date,Long bankAccountId){if(provider==null||provider.isBlank()||providerReference==null||providerReference.isBlank())throw new IllegalArgumentException("Provider and provider reference are required");if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Settlement amount must be positive");if(internalRef!=null&&!internalRef.isBlank()){Payment payment=paymentRepo.findByPaymentReference(internalRef.trim()).orElseThrow(()->new IllegalArgumentException("Internal payment reference not found: "+internalRef));if(payment.getOrganization()==null||!org.getId().equals(payment.getOrganization().getId()))throw new SecurityException("Cross-organization payment settlement denied");BigDecimal internalAmount=payment.getAmountPaid()==null?BigDecimal.ZERO:payment.getAmountPaid();if(internalAmount.subtract(amount).abs().compareTo(new BigDecimal("0.01"))>0)throw new IllegalStateException("Settlement amount does not match internal payment amount");}if(repo.findByOrganization_IdAndProviderAndProviderReference(org.getId(),provider.trim().toUpperCase(Locale.ROOT),providerReference.trim()).isPresent())throw new IllegalStateException("Settlement already exists for provider reference");return repo.save(PaymentSettlement.builder().organization(org).provider(provider.trim().toUpperCase(Locale.ROOT)).providerReference(providerReference.trim()).internalPaymentReference(internalRef).amount(amount.setScale(2,RoundingMode.HALF_UP)).currency(currency==null?"RWF":currency.trim().toUpperCase(Locale.ROOT)).settlementDate(date==null?LocalDate.now():date).bankAccountId(bankAccountId).build());}
 @Transactional public PaymentSettlement reconcile(Organization org,Long settlementId,Long statementLineId,String actor){PaymentSettlement s=repo.findById(settlementId).orElseThrow(()->new IllegalArgumentException("Settlement not found"));if(!org.getId().equals(s.getOrganization().getId()))throw new SecurityException("Cross-organization settlement access denied");BankStatementLine b=statementRepo.findForUpdate(statementLineId,org.getId()).orElseThrow(()->new IllegalArgumentException("Bank statement line not found"));if(!Objects.equals(s.getCurrency(),b.getCurrency()))throw new IllegalStateException("Settlement currency does not match statement currency");BigDecimal diff=s.getAmount().subtract(b.getAmount()).setScale(2,RoundingMode.HALF_UP);if(diff.abs().compareTo(new BigDecimal("0.01"))>0)throw new IllegalStateException("Settlement and bank statement amount do not match: "+diff);s.setStatus("RECONCILED");s.setBankStatementLineId(b.getId());s.setDifference(diff);s.setMatchedAt(LocalDateTime.now());b.setReconciliationStatus("MATCHED");b.setMatchedBy(actor);b.setMatchedAt(LocalDateTime.now());statementRepo.save(b);return repo.save(s);}
 @Transactional(readOnly=true) public List<PaymentSettlement> pending(Organization org){return repo.findByOrganization_IdAndStatusOrderBySettlementDateAsc(org.getId(),"UNRECONCILED");}
}
